\node[below right] at (0.65,0) {$c$};
\fill (0.65,1.3) circle (1.3pt);
\fill (0.65,-1.3) circle (1.3pt);
\node[right] at (0.65,1.3) {$(c,2c)$};
\node[right] at (0.65,-1.3) {$(c,-2c)$};
